using System.Diagnostics;
using System.Net.Http;
using System.Reflection;
using System.Security.Cryptography;
using System.Text.Json;
using System.Text.RegularExpressions;
namespace WirePulse;

public sealed record ReleaseVersion(int Major,int Minor,int Patch,string Pre=""):IComparable<ReleaseVersion>
{
 public static ReleaseVersion? Parse(string value){var match=Regex.Match(value,@"^v?(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z.-]+))?(?:\+[0-9A-Za-z.-]+)?$");if(!match.Success||!int.TryParse(match.Groups[1].Value,out int a)||!int.TryParse(match.Groups[2].Value,out int b)||!int.TryParse(match.Groups[3].Value,out int c))return null;string pre=match.Groups[4].Value;if(pre.Length>0&&pre.Split('.').Any(x=>x.Length==0||(x.All(char.IsDigit)&&x.Length>1&&x[0]=='0')))return null;return new(a,b,c,pre);}
 public string Core=>$"{Major}.{Minor}.{Patch}";
 public int CompareTo(ReleaseVersion? other){if(other==null)return 1;int c=Major.CompareTo(other.Major);if(c==0)c=Minor.CompareTo(other.Minor);if(c==0)c=Patch.CompareTo(other.Patch);if(c!=0)return c;if(Pre==other.Pre)return 0;if(Pre.Length==0)return 1;if(other.Pre.Length==0)return -1;var a=Pre.Split('.');var b=other.Pre.Split('.');for(int i=0;i<Math.Min(a.Length,b.Length);i++){bool na=a[i].All(char.IsDigit),nb=b[i].All(char.IsDigit);c=na&&nb?(a[i].Length==b[i].Length?string.CompareOrdinal(a[i],b[i]):a[i].Length.CompareTo(b[i].Length)):na!=nb?(na?-1:1):string.CompareOrdinal(a[i],b[i]);if(c!=0)return c;}return a.Length.CompareTo(b.Length);}
}
public sealed record UpdateAsset(string Name,string Url,long Size,string Digest);
public sealed record UpdateRelease(string Tag,ReleaseVersion Version,bool Prerelease,UpdateAsset Asset,UpdateAsset? Checksums);
public sealed class UpdatePreferences {public string Channel{get;set;}="stable";public bool Automatic{get;set;}=true;public string Skipped{get;set;}="";}
public sealed class UpdateService
{
 public const string Repository="JLiveOf/wirepulse";
 // Initialize the case-insensitive options before Current loads persisted preferences.
 static readonly JsonSerializerOptions json=new(){PropertyNamingPolicy=JsonNamingPolicy.CamelCase,PropertyNameCaseInsensitive=true};
 static readonly HttpClient http=CreateClient();static HttpClient CreateClient(){var c=new HttpClient{Timeout=TimeSpan.FromMinutes(15),MaxResponseContentBufferSize=8*1024*1024};c.DefaultRequestHeaders.UserAgent.ParseAdd("WirePulse/4.2.0");c.DefaultRequestHeaders.Accept.ParseAdd("application/vnd.github+json");return c;}
 public static string BuildVersion=>typeof(UpdateService).Assembly.GetCustomAttribute<AssemblyInformationalVersionAttribute>()?.InformationalVersion.Split('+')[0]??"4.2.0";
 public sealed record InstalledRelease(string Tag,string Hash);
 static readonly Lazy<string> installed=new(()=>{try{var marker=JsonSerializer.Deserialize<InstalledRelease>(File.ReadAllText(MarkerPath),new JsonSerializerOptions{PropertyNameCaseInsensitive=true});return ResolveInstalled(BuildVersion,marker,FileHash(BinaryPath));}catch{return BuildVersion;}});
 public static string InstalledVersion=>installed.Value;
 static string BinaryPath=>string.IsNullOrEmpty(typeof(UpdateService).Assembly.Location)?Environment.ProcessPath!:typeof(UpdateService).Assembly.Location;
 static string MarkerPath=>Path.Combine(Settings.Folder,"Installed",Convert.ToHexString(SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(Path.GetFullPath(AppContext.BaseDirectory))))+".json");
 static string FileHash(string path){using var stream=File.OpenRead(path);return Convert.ToHexString(SHA256.HashData(stream));}
 public static string ResolveInstalled(string build,InstalledRelease? marker,string hash)=>marker!=null&&ReleaseVersion.Parse(marker.Tag) is{} tag&&ReleaseVersion.Parse(build)?.Core==tag.Core&&string.Equals(marker.Hash,hash,StringComparison.OrdinalIgnoreCase)?marker.Tag.TrimStart('v'):build;
 static void WriteMarker(string tag,string hash){Directory.CreateDirectory(Path.GetDirectoryName(MarkerPath)!);File.WriteAllText(MarkerPath,JsonSerializer.Serialize(new InstalledRelease(tag,hash)));}
 public static int RecordInstalledTag(string tag){var parsed=ReleaseVersion.Parse(tag);if(parsed==null||parsed.Core!=ReleaseVersion.Parse(BuildVersion)?.Core)return 1;WriteMarker(tag,FileHash(BinaryPath));return 0;}
 public static async Task RecordDebPackageAsync(string package,string tag){var start=new ProcessStartInfo("dpkg-deb"){UseShellExecute=false,RedirectStandardOutput=true};start.ArgumentList.Add("--fsys-tarfile");start.ArgumentList.Add(package);using var process=Process.Start(start)??throw new IOException("No se pudo leer el paquete Debian.");string? hash=null;using(var reader=new System.Formats.Tar.TarReader(process.StandardOutput.BaseStream)){System.Formats.Tar.TarEntry? entry;while((entry=await reader.GetNextEntryAsync())!=null){if(entry.Name.TrimStart('.','/')=="opt/wirepulse/WirePulse.dll"&&entry.DataStream!=null)hash=Convert.ToHexString(await SHA256.HashDataAsync(entry.DataStream));}}await process.WaitForExitAsync();if(process.ExitCode!=0||hash==null)throw new InvalidDataException("El paquete no contiene WirePulse.");WriteMarker(tag,hash);}
 public static readonly UpdateService Current=new(Program.Option("--update-preferences-probe"));
 readonly string file;int checking;public string Status{get;private set;}="";public UpdatePreferences Preferences{get;private set;}=new();public event Action<UpdateRelease>? Available;
 public UpdateService(string? path=null){file=path??Path.Combine(Settings.Folder,"updates.json");try{Preferences=JsonSerializer.Deserialize<UpdatePreferences>(File.ReadAllText(file),json)??new();}catch{}if(Preferences.Channel is not("stable" or "beta"))Preferences.Channel="stable";}
 public void Configure(string? channel=null,bool? automatic=null,string? skipped=null){if(channel!=null)Preferences.Channel=channel=="beta"?"beta":"stable";if(automatic!=null)Preferences.Automatic=automatic.Value;if(skipped!=null)Preferences.Skipped=skipped;Directory.CreateDirectory(Path.GetDirectoryName(file)!);string temp=file+".tmp-"+Guid.NewGuid();File.WriteAllText(temp,JsonSerializer.Serialize(Preferences,json));File.Move(temp,file,true);}
 public static bool Trusted(string url)=>Uri.TryCreate(url,UriKind.Absolute,out var uri)&&uri.Scheme=="https"&&uri.Host=="github.com"&&uri.AbsolutePath.StartsWith("/"+Repository+"/releases/download/",StringComparison.Ordinal)&&uri.UserInfo.Length==0;
 public static UpdateRelease? Select(string json,string current,string channel,string platform,string skipped=""){
  var installed=ReleaseVersion.Parse(current);if(installed==null)return null;var candidates=new List<UpdateRelease>();using var doc=JsonDocument.Parse(json);
  foreach(var release in doc.RootElement.EnumerateArray()){
   if(release.GetProperty("draft").GetBoolean())continue;bool pre=release.GetProperty("prerelease").GetBoolean();if(channel!="beta"&&pre)continue;string tag=release.GetProperty("tag_name").GetString()??"";var version=ReleaseVersion.Parse(tag);if(version==null||version.CompareTo(installed)<=0||ReleaseVersion.Parse(skipped)?.CompareTo(version)==0)continue;if(channel!="beta"&&version.Pre.Length>0)continue;
   var assets=release.GetProperty("assets").EnumerateArray().Select(a=>new UpdateAsset(a.GetProperty("name").GetString()??"",a.GetProperty("browser_download_url").GetString()??"",a.GetProperty("size").GetInt64(),a.TryGetProperty("digest",out var digest)?digest.GetString()??"":"")).Where(a=>Trusted(a.Url)&&a.Name==Path.GetFileName(a.Name)&&a.Size>0&&a.Size<=1024L*1024*1024).ToArray();
   string suffix=platform switch{"windows"=>"-win-x64-Setup.exe","linux-deb"=>"_amd64.deb","linux"=>"-linux-x64.tar.gz","macos"=>"-macOS-arm64.zip",_=>"!unsupported"};var asset=assets.FirstOrDefault(a=>a.Name.EndsWith(suffix,StringComparison.Ordinal));if(asset==null)continue;var checksum=assets.FirstOrDefault(a=>a.Name=="SHA256SUMS.txt");if(!asset.Digest.StartsWith("sha256:",StringComparison.Ordinal)&&checksum==null)continue;candidates.Add(new(tag,version,pre,asset,checksum));
  }return candidates.OrderByDescending(c=>c.Version).FirstOrDefault();
 }
 public static string Platform=>OperatingSystem.IsWindows()?"windows":OperatingSystem.IsMacOS()?"macos":AppContext.BaseDirectory.TrimEnd(Path.DirectorySeparatorChar)=="/opt/wirepulse"?"linux-deb":"linux";
 public async Task CheckAsync(bool manual=false){if(!manual&&!Preferences.Automatic)return;if(Interlocked.Exchange(ref checking,1)!=0)return;try{Status="Buscando actualizaciones…";using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(25));string json=await http.GetStringAsync("https://api.github.com/repos/"+Repository+"/releases?per_page=100",timeout.Token);var result=Select(json,InstalledVersion,Preferences.Channel,Platform,manual?"":Preferences.Skipped);Status=result==null?"Ya tienes la versión más reciente.":"Nueva versión disponible: "+result.Tag;if(result!=null)Available?.Invoke(result);}catch(Exception e){Status="No se pudieron comprobar las actualizaciones: "+e.Message;}finally{Volatile.Write(ref checking,0);}}
 public static bool HashMatches(string path,string expected){using var stream=File.OpenRead(path);return string.Equals(Convert.ToHexString(SHA256.HashData(stream)),expected,StringComparison.OrdinalIgnoreCase);}
 public async Task<string> DownloadAsync(UpdateRelease release,IProgress<double>? progress,CancellationToken cancel){if(!Trusted(release.Asset.Url))throw new InvalidDataException("Origen de actualización no válido.");string expected=release.Asset.Digest.StartsWith("sha256:")?release.Asset.Digest[7..]:"";if(expected.Length==0){if(release.Checksums==null||!Trusted(release.Checksums.Url))throw new InvalidDataException("Falta la suma de verificación.");using var response=await http.GetAsync(release.Checksums.Url,HttpCompletionOption.ResponseHeadersRead,cancel);response.EnsureSuccessStatusCode();if(response.Content.Headers.ContentLength>1024*1024)throw new InvalidDataException("Manifiesto demasiado grande.");string text=await response.Content.ReadAsStringAsync(cancel);if(text.Length>1024*1024)throw new InvalidDataException("Manifiesto demasiado grande.");foreach(string line in text.Split('\n')){var match=Regex.Match(line.Trim(),@"^([a-fA-F0-9]{64})\s+\*?(.+)$");if(match.Success&&match.Groups[2].Value==release.Asset.Name){expected=match.Groups[1].Value;break;}}}if(!Regex.IsMatch(expected,"^[0-9a-fA-F]{64}$"))throw new InvalidDataException("Suma de verificación no válida.");string directory=Path.Combine(Settings.Folder,"Updates",release.Tag.TrimStart('v'));Directory.CreateDirectory(directory);string path=Path.Combine(directory,release.Asset.Name),part=path+".part-"+Guid.NewGuid();try{using var response=await http.GetAsync(release.Asset.Url,HttpCompletionOption.ResponseHeadersRead,cancel);response.EnsureSuccessStatusCode();await using(var source=await response.Content.ReadAsStreamAsync(cancel))await using(var output=File.Create(part)){byte[] buffer=new byte[131072];long total=0;int read;while((read=await source.ReadAsync(buffer,cancel))>0){total+=read;if(total>release.Asset.Size||total>1024L*1024*1024)throw new InvalidDataException("Tamaño de actualización no válido.");await output.WriteAsync(buffer.AsMemory(0,read),cancel);progress?.Report((double)total/release.Asset.Size);}if(total!=release.Asset.Size)throw new InvalidDataException("Descarga incompleta.");}if(!HashMatches(part,expected))throw new InvalidDataException("La actualización no supera la verificación SHA-256.");File.Move(part,path,true);Status="Actualización descargada y verificada.";return path;}finally{if(File.Exists(part))File.Delete(part);}}
}
